'use client';
import { useForm } from 'react-hook-form';
import { zodResolver } from '@hookform/resolvers/zod';
import { z } from 'zod';

const schema = z.object({
  email: z.string().email(),
  password: z.string().min(8),
});
type Data = z.infer<typeof schema>;

export function {{form_name}}() {
  const { register, handleSubmit, formState: { errors, isSubmitting } } = useForm<Data>({ resolver: zodResolver(schema) });
  return (
    <form onSubmit={handleSubmit(async (d) => { await fetch('/api/login', { method:'POST', body: JSON.stringify(d) }); })}>
      <input {...register('email')} placeholder="email" />
      {errors.email && <p>{errors.email.message}</p>}
      <input type="password" {...register('password')} />
      {errors.password && <p>{errors.password.message}</p>}
      <button disabled={isSubmitting}>登入</button>
    </form>
  );
}
